import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    X = int(data[0])
    K = int(data[1])
    D = int(data[2])

    # Move towards zero as much as possible
    if X >= 0:
        moves = X // D
    else:
        moves = -(X // D)
        if X % D != 0:
            moves += 1

    if K >= moves:
        # We can reach zero or cross it
        remaining = K - moves
        if remaining % 2 == 0:
            ans = 0
        else:
            # One step away from zero
            ans = D
    else:
        # Cannot reach zero, stop at the closest point towards zero
        ans = abs(X - moves * D)

    print(ans)

if __name__ == "__main__":
    solve()
